(() => {
'use strict';
const D=window.COOKXUAN_CATALOG, recipes=D.recipes, byId=new Map(recipes.map(r=>[r.id,r]));
const $=(s,root=document)=>root.querySelector(s), $$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=n=>`<svg aria-hidden="true"><use href="#i-${n}"/></svg>`;
const Reading=window.CookXuanReading;
const defaults={pantry:['番茄','鸡蛋','面条','西兰花'],seasonings:['盐','食用油','生抽','糖','大蒜'],favorites:[],shopping:[],cooked:[],servings:1};
let S=JSON.parse(JSON.stringify(defaults));
try{const old=JSON.parse(localStorage.getItem('cookxuan-v2')||localStorage.getItem('cookxuan-v1')||'null');if(old){const strings=(x,f)=>Array.isArray(x)?[...new Set(x.filter(v=>typeof v==='string'&&v.length<=40))]:f;S={...S,pantry:strings(old.pantry,S.pantry).slice(0,60),seasonings:strings(old.seasonings,S.seasonings),favorites:strings(old.favorites,[]).map(id=>id==='tomato-eggs'?recipes.find(r=>r.name==='西红柿炒鸡蛋')?.id:id==='garlic-broccoli'?recipes.find(r=>r.name==='蒜蓉西兰花'&&!r.editorial)?.id:id).filter(id=>byId.has(id)),shopping:Array.isArray(old.shopping)?old.shopping.filter(i=>i&&typeof i.name==='string'&&i.name.length<=30).map(i=>({name:i.name,done:!!i.done})).slice(0,100):[],cooked:Array.isArray(old.cooked)?old.cooked.filter(c=>c&&byId.has(c.id)).slice(0,100):[],servings:Number.isInteger(old.servings)?Math.max(1,Math.min(6,old.servings)):1};}}catch{}
let route='',category='全部',query='',filter='全部',limit=24,matching=false,pantryTab='食材',myTab='收藏',recipeTab='备菜',currentRecipeId='',stepIndex=0,featuredOffset=0,toastHandle,searchHandle,installPrompt,timerInterval,timerDeadline=0,timerLeft=0,timerRecipe='',timerStep=-1,wakeLock;
const initialRoute=location.hash.slice(1)||'home';history.replaceState({cx:true,depth:0},'','#'+initialRoute);
function save(){try{localStorage.setItem('cookxuan-v2',JSON.stringify(S));}catch{}}
function toast(text){clearTimeout(toastHandle);$('#toast').textContent=text;$('#toast').classList.add('show');toastHandle=setTimeout(()=>$('#toast').classList.remove('show'),2600);}
function english(name){return D.dictionary[name]?.[0]||'';}
function canonical(raw){const val=raw.normalize('NFKC').trim(),key=val.toLowerCase();return D.synonyms[val]||Object.entries(D.dictionary).find(([n,aliases])=>n===val||aliases.some(a=>a.toLowerCase()===key))?.[0]||val;}
const emojiMap={'番茄':'🍅','鸡蛋':'🥚','面条':'🍜','意面':'🍝','西兰花':'🥦','豆腐':'◻️','鸡腿':'🍗','鸡胸肉':'🍗','米饭':'🍚','大米':'🍚','土豆':'🥔','胡萝卜':'🥕','蘑菇':'🍄','香菇':'🍄','大蒜':'🧄','洋葱':'🧅','辣椒':'🌶️','黄瓜':'🥒','茄子':'🍆','玉米':'🌽','小麦粉':'🌾','牛奶':'🥛','牛肉':'🥩','猪肉':'🥩','虾':'🦐','白菜':'🥬','青菜':'🥬','香葱':'🌱','姜':'🫚','豌豆':'🫛'};
function emoji(name){return emojiMap[name]||'🌿';}
function isWater(name){return /^(?:清水|开水|饮用水|冷水|热水|温水|沸水|纯净水|矿泉水|水)$/.test(name);}
function available(item){const name=typeof item==='string'?item:item.name;const options=[name,...(typeof item==='object'?item.alternatives||[]:[])].map(canonical);const have=[...S.pantry,...S.seasonings].map(canonical);return isWater(name)||options.some(n=>have.some(h=>h===n||(h.length>=2&&n.includes(h)&&n.length-h.length<=3)));}
function isSeasoning(name){return D.seasonings.includes(canonical(name))||/(?:酱油|酱汁|粉|调料|食盐|油|料酒|米酒|白酒|香料|孜然|八角|桂皮|冰糖|白砂糖|胡椒|辣椒酱|番茄酱|咖喱|味精)$/.test(name);}
function mainIngredients(r){return r.ingredients.filter(i=>!i.optional&&!isSeasoning(i.name)&&!isWater(i.name));}
function misses(r){return r.ingredients.filter(i=>!i.optional&&!available(i));}
function score(r){const main=mainIngredients(r);const count=main.filter(available).length;return main.length?count/main.length:0;}
function level(r){return r.editorial?(r.difficulty.includes('火候')?'进阶':'新手'):r.difficulty?(r.difficulty<=2?'新手':r.difficulty===3?'进阶':'挑战'):r.category;}
function matchingRecipes(){let list=recipes.filter(r=>(category==='全部'||r.category===category)&&(!query||[r.name,r.category,...r.ingredients.map(i=>i.name),r.description].join(' ').toLowerCase().includes(query.toLowerCase())));if(filter==='新手友好')list=list.filter(r=>level(r)==='新手');if(filter==='20 分钟')list=list.filter(r=>r.time&&r.time<=20);if(filter==='食材齐了')list=list.filter(r=>!misses(r).length);if(matching){list=list.filter(r=>score(r)>0);list.sort((a,b)=>score(b)-score(a)||misses(a).length-misses(b).length||Number(b.editorial)-Number(a.editorial));}return list;}
function photo(r,cls=''){if(r.editorial&&r.image?.startsWith('q'))return `<div class="recipe-photo atlas ${r.image} ${cls}"><img src="assets/dishes.webp" alt="${esc(r.name)}" loading="lazy"></div>`;if(r.cover)return `<div class="recipe-photo ${cls}"><img src="${esc(r.cover.replace('assets/hero.png.webp','assets/hero.webp.webp'))}" alt="${esc(r.name)}" loading="lazy"></div>`;return `<div class="recipe-photo placeholder cat-${esc(r.category)} ${cls}">${icon(r.category==='素菜'?'leaf':r.category==='饮品'?'clock':'chef')}<span>${esc(r.category)}</span></div>`;}
function meta(r){return `${r.time?`<span>${icon('clock')}${r.time} 分钟</span>`:''}<span>${level(r)}</span>`;}
function card(r,match=false){const saved=S.favorites.includes(r.id),m=misses(r);return `<article class="recipe-card"><button class="card-heart ${saved?'saved':''}" data-favorite="${r.id}" aria-pressed="${saved}" aria-label="${saved?'取消收藏':'收藏'}${esc(r.name)}">${icon('heart')}</button><button class="card-open" data-recipe="${r.id}" aria-label="查看${esc(r.name)}">${photo(r)}${match?`<span class="match-badge ${m.length?'missing':''}">${m.length?'缺 '+m.length+' 样':'食材齐了'}</span>`:''}<div class="card-copy"><h3>${esc(r.name)}</h3><div class="card-meta">${meta(r)}</div></div></button></article>`;}
function listCard(r){return `<button class="list-recipe card-open" data-recipe="${r.id}" aria-label="查看${esc(r.name)}">${photo(r)}<span class="list-info"><h3>${esc(r.name)}</h3><span class="card-meta">${meta(r)}</span></span>${icon('arrow')}</button>`;}
function empty(title,copy,action='library',label='浏览菜谱'){return `<div class="empty">${icon('chef')}<h2>${title}</h2>${copy?`<p>${copy}</p>`:''}<button class="outline" data-go="${action}">${label}${icon('arrow')}</button></div>`;}
function go(next,replace=false){if(next===route)return;const depth=history.state?.depth||0;history[replace?'replaceState':'pushState']({cx:true,depth:replace?depth:depth+1},'','#'+next);renderRoute(next);}
function back(){if((history.state?.depth||0)>0)history.back();else go('home',true);}
function renderRoute(next){const prev=route;route=next;const isDetail=next.startsWith('recipe/'),isCook=next.startsWith('cook/');document.body.classList.toggle('detail-mode',isDetail);document.body.classList.toggle('cook-mode',isCook);if(!isCook){stopTimer();releaseWakeLock();}$$('#bottom-nav button').forEach(b=>{b.classList.toggle('active',b.dataset.go===next);if(b.dataset.go===next)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});if(isDetail){const r=byId.get(next.slice(7));if(!r){go('library',true);return;}if(currentRecipeId!==r.id)recipeTab='备菜';currentRecipeId=r.id;renderDetail(r);}else if(isCook){const r=byId.get(next.slice(5));if(!r){go('library',true);return;}if(!prev.startsWith('cook/'))stepIndex=0;currentRecipeId=r.id;renderCook(r);requestWakeLock();}else if(next==='pantry')renderPantry();else if(next==='library')renderLibrary();else if(next==='me')renderMe();else renderHome();window.scrollTo({top:0,behavior:'instant'});document.title=isDetail||isCook?`${byId.get(currentRecipeId)?.name} · CookXuan`:'CookXuan';}
function renderHome(){const feature=recipes.find(r=>r.id==='tomato-noodles');const picks=recipes.filter(r=>r.editorial&&r.id!==feature.id);const selected=[...picks.slice(featuredOffset),...picks.slice(0,featuredOffset)].slice(0,2);const sourcePicks=recipes.filter(r=>!r.editorial&&r.cover&&r.difficulty&&r.difficulty<=2).slice(featuredOffset*3,featuredOffset*3+3);$('#screen').innerHTML=`<button class="hero-card" data-recipe="${feature.id}" aria-label="查看番茄鸡蛋暖心面"><img src="assets/hero.webp.webp" alt="番茄鸡蛋面"><div class="hero-copy"><span>15 分钟 · 一人食</span><h2>番茄鸡蛋面</h2></div></button><section class="pantry-card"><div class="row-heading"><h2>${icon('fridge')}冰箱</h2><button class="text-button" data-open-pantry>编辑 ${icon('plus')}</button></div><div class="tags">${S.pantry.slice(0,3).map(n=>`<button class="tag" data-open-pantry>${esc(n)}</button>`).join('')}<button class="tag tag-add" data-open-pantry aria-label="添加食材">${icon('plus')}${S.pantry.length>3?S.pantry.length-3:''}</button></div><button class="primary full" data-match>找菜谱 ${icon('arrow')}</button></section><div class="section-heading"><h2>精选</h2><button class="text-button" id="shuffle">${icon('refresh')}换一换</button></div><div class="recipe-grid">${selected.map(r=>card(r)).join('')}</div><div class="section-heading"><h2>菜谱</h2><button class="text-button" data-go="library">全部 ${icon('arrow')}</button></div>${sourcePicks.map(listCard).join('')}`;}
function renderLibrary(){const matches=matchingRecipes();$('#screen').innerHTML=`<div class="page-heading"><h1>${matching?'用现有食材，开饭。':'你的随身菜谱。'}</h1></div><label class="search-box">${icon('search')}<input id="recipe-search" value="${esc(query)}" placeholder="搜菜名，也能搜食材" aria-label="搜索菜谱" autocomplete="off"><button id="clear-search" aria-label="清除搜索" ${query?'':'hidden'}>${icon('x')}</button></label><div class="chips" id="categories">${['全部','主食','素菜','荤菜','水产','早餐','汤粥','甜品','饮品','酱料','半成品'].map(c=>`<button class="chip ${c===category?'active':''}" data-category="${c}" aria-pressed="${c===category}">${c}</button>`).join('')}</div><div class="filters">${['全部','新手友好','20 分钟','食材齐了'].map(f=>`<button class="filter ${filter===f?'active':''}" data-filter="${f}" aria-pressed="${filter===f}">${f}</button>`).join('')}${matching?'<button class="filter" id="show-all">退出食材匹配</button>':''}</div><div id="library-results">${libraryResults(matches)}</div>`;}
function libraryResults(list){return `<p class="results-count">${query?`找到 ${list.length} 道`:`${list.length} 道${matching?'适合你的菜':'菜，慢慢挑'}`}</p><div class="recipe-grid">${list.length?list.slice(0,limit).map(r=>card(r,matching)).join(''):empty('换个搭配试试','','reset-library','看全部菜谱')}</div>${list.length>limit?`<button class="load-more" id="load-more">再看 ${Math.min(24,list.length-limit)} 道</button>`:''}`;}
function updateLibraryResults(){const el=$('#library-results');if(el)el.innerHTML=libraryResults(matchingRecipes());const clear=$('#clear-search');if(clear)clear.hidden=!query;}
function pantryContents(){return `<form class="inventory-form" id="ingredient-form"><input id="ingredient-input" placeholder="番茄、鸡蛋、土豆…" maxlength="140" aria-label="添加食材" autocomplete="off"><button type="submit" aria-label="添加食材">${icon('plus')}</button></form><div class="inventory-grid">${S.pantry.map(n=>`<article class="inventory-item"><span class="ingredient-emoji" aria-hidden="true">${emoji(n)}</span><div><h3>${esc(n)}</h3>${english(n)?`<p>${esc(english(n))}</p>`:''}</div><button data-remove="${esc(n)}" aria-label="移除${esc(n)}">${icon('x')}</button></article>`).join('')}</div><div class="section-heading"><h2>常买食材</h2></div><div class="suggestions">${['鸡腿','豆腐','蘑菇','土豆','胡萝卜','米饭','牛奶','牛肉','黄瓜','香菇'].filter(n=>!S.pantry.includes(n)).slice(0,7).map(n=>`<button class="suggestion" data-add="${esc(n)}">${icon('plus')}${n}</button>`).join('')}</div><details class="seasonings-block"><summary>调料 · ${S.seasonings.length} 样</summary><div class="suggestions">${D.seasonings.map(n=>`<button class="suggestion ${S.seasonings.includes(n)?'selected':''}" data-seasoning="${n}" aria-pressed="${S.seasonings.includes(n)}">${icon(S.seasonings.includes(n)?'check':'plus')}${n}</button>`).join('')}</div></details><button class="primary full sticky-match" data-match>找菜谱 ${icon('arrow')}</button>`;}
function renderPantry(){const remaining=S.shopping.filter(x=>!x.done).length;$('#screen').innerHTML=`<div class="page-heading"><h1>我的冰箱</h1></div><div class="segmented"><button class="${pantryTab==='食材'?'active':''}" data-pantry-tab="食材">食材 ${S.pantry.length}</button><button class="${pantryTab==='采购'?'active':''}" data-pantry-tab="采购">采购${remaining?' '+remaining:''}</button></div>${pantryTab==='食材'?pantryContents():shoppingContents()}`;}
function shoppingContents(){return `<form class="inventory-form" id="shopping-form"><input id="shopping-input" maxlength="30" placeholder="下次买什么？" aria-label="添加采购项"><button type="submit" aria-label="添加采购项">${icon('plus')}</button></form>${S.shopping.length?S.shopping.map((item,i)=>`<div class="shopping-row ${item.done?'done':''}"><input type="checkbox" id="buy-${i}" data-buy="${i}" ${item.done?'checked':''}><label for="buy-${i}">${esc(item.name)}${english(item.name)?`<small>${esc(english(item.name))}</small>`:''}</label><button data-remove-shopping="${i}" aria-label="删除${esc(item.name)}">${icon('x')}</button></div>`).join(''):empty('采购单为空','','library','浏览菜谱')}<div class="shopping-actions"><button class="outline" id="move-bought">${icon('fridge')}已买的放进冰箱</button><button class="text-button" id="copy-shopping">复制</button></div>`;}
function renderMe(){const list=myTab==='收藏'?recipes.filter(r=>S.favorites.includes(r.id)):[...S.cooked].reverse().map(c=>byId.get(c.id)).filter(Boolean);$('#screen').innerHTML=`<header class="profile-head"><span class="profile-avatar">C</span><div><h1>我的</h1></div></header><div class="profile-menu"><button id="install-app">${icon('download')}添加到手机桌面${icon('arrow')}</button><button id="source-info">${icon('book')}完整菜谱库<span>${D.meta.sourceRecipeCount} 道原方</span>${icon('arrow')}</button><button id="learn">${icon('chef')}厨房小课堂${icon('arrow')}</button></div><div class="segmented"><button class="${myTab==='收藏'?'active':''}" data-my-tab="收藏">收藏 ${S.favorites.length}</button><button class="${myTab==='做过'?'active':''}" data-my-tab="做过">做过 ${S.cooked.length}</button></div><div class="recipe-grid">${list.length?list.map(r=>card(r)).join(''):empty(myTab==='收藏'?'暂无收藏':'暂无记录',myTab==='收藏'?'':'')}</div>`;}
function addFood(raw){const names=raw.split(/[,，、;；\n]+/).map(canonical).filter(Boolean);let count=0;for(const name of names){if(name.length>24)continue;const target=D.seasonings.includes(name)?S.seasonings:S.pantry;if(!target.includes(name)&&target.length<60){target.push(name);count++;}}if(!count){toast(names.length?'已经在厨房里了':'先写一种食材');return;}save();toast(`放进冰箱了 · ${count} 样`);refreshPantry();}
function refreshPantry(){if($('#sheet').open&&$('#sheet-content #ingredient-form'))renderPantrySheet();else if(route==='pantry')renderPantry();else if(route==='home')renderHome();else if(route==='library')updateLibraryResults();}
function openSheet(html){$('#sheet-content').innerHTML=html;$('#sheet').showModal();}
function renderPantrySheet(){const y=$('#sheet').scrollTop;$('#sheet-content').innerHTML='<h2>冰箱什么？</h2>'+pantryContents();$('#sheet').scrollTop=y;}
function openPantry(){renderPantrySheet();$('#sheet').showModal();}
function toggleFavorite(id){if(!byId.has(id))return;S.favorites=S.favorites.includes(id)?S.favorites.filter(n=>n!==id):[...S.favorites,id];save();const saved=S.favorites.includes(id);$$(`[data-favorite="${id}"]`).forEach(b=>{b.classList.toggle('saved',saved);b.setAttribute('aria-pressed',saved);b.setAttribute('aria-label',(saved?'取消收藏':'收藏')+byId.get(id).name);});if(route==='me')renderMe();toast(saved?'已收藏':'已移出收藏');}
function scaled(text){return text.replace(/\{\{([\d.]+)\}\}/g,(_,n)=>+(+n*S.servings).toFixed(1));}
function amount(i){const n=i.amount*S.servings;return `${i.unit==='个'||i.unit==='瓣'?Math.ceil(n):+n.toFixed(1)} ${i.unit}`;}
function plain(t){return String(t||'').replace(/\[([^\]]+)\]\([^)]*\)/g,'$1').replace(/[`*_]/g,'').trim();}
function inline(t,r){
 const tokens=[],token=html=>{tokens.push(html);return `\u0001${tokens.length-1}\u0002`;};
 let raw=String(t).replace(/!\[([^\]]*)\]\(((?:[^()]|\([^()]*\))*)\)/g,(_,alt,ref)=>{const image=r?.photos?.find(p=>p.ref===ref),src=image?.src||image?.remote;return src?token(`<img src="${esc(src)}" alt="${esc(alt)}" loading="lazy">`):'';});
 raw=raw.replace(/\[([^\]]+)\]\(([^)]+)\)/g,(_,label,target)=>{let href='';try{const base=r?.sourceUrl?.replace('github.com/','raw.githubusercontent.com/').replace('/blob/','/'),url=new URL(target,base||location.href);if(['https:','http:'].includes(url.protocol))href=url.href;}catch{}return href?token(`<a href="${esc(href)}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`):label;});
 return esc(raw).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\u0001(\d+)\u0002/g,(_,i)=>tokens[+i]);
}
function markdown(text,r){const lines=String(text||'').split('\n');let out='',list='',code=false,codeText=[];const close=()=>{if(list){out+=`</${list}>`;list='';}};for(const line of lines){if(/^```/.test(line)){close();if(code){out+='<pre>'+esc(codeText.join('\n'))+'</pre>';codeText=[];}code=!code;continue;}if(code){codeText.push(line);continue;}if(!line.trim()){close();continue;}const h=line.match(/^(#{1,6})\s+(.+)$/);if(h){close();const level=Math.min(h[1].length,3);out+=`<h${level}>${inline(h[2],r)}</h${level}>`;continue;}const li=line.match(/^\s*(?:([-*+])\s+|(\d+)[.)]\s+)(.+)$/);if(li){const type=li[1]?'ul':'ol';if(list!==type){close();out+=`<${type}>`;list=type;}out+=`<li>${inline(li[3],r)}</li>`;continue;}close();if(/^\s*\|/.test(line)){if(/^\s*\|?\s*:?[-–]{2}/.test(line))continue;out+='<p>'+inline(line,r)+'</p>';}else out+='<p>'+inline(line,r)+'</p>';}close();if(code&&codeText.length)out+='<pre>'+esc(codeText.join('\n'))+'</pre>';return out;}
function processPhoto(index){return `<div class="process-photo p${index}"><img src="assets/steps-noodles.webp.webp" alt="第 ${index+1} 步"></div>`;}
function ingredientContent(r){const missing=misses(r);let html=`<div class="portion-row"><span>食材</span>${r.editorial?`<div class="counter"><button data-serving="-1" aria-label="减少人数" ${S.servings===1?'disabled':''}>−</button><span>${S.servings} 人份</span><button data-serving="1" aria-label="增加人数" ${S.servings===6?'disabled':''}>+</button></div>`:''}</div>`;
html+=r.ingredients.map(i=>`<div class="ingredient-row ${available(i)?'':'lacking'}">${icon(available(i)?'check':'plus')}<span>${esc(r.editorial?i.name:i.raw||i.name)}${i.optional?' <span class="optional">可选</span>':''}${r.editorial&&english(i.name)?`<small>${esc(english(i.name))}${i.note?' · '+esc(i.note):''}</small>`:''}</span>${r.editorial?`<span class="qty">${amount(i)}</span>`:''}</div>`).join('');
if(missing.length)html+=`<p class="missing-line">${icon('bag')}还缺 ${missing.map(i=>esc(i.name)).join('、')}</p>`;
if(!r.editorial&&r.calculation)html+=`<details class="detail-extra"><summary>看用量</summary><div class="prose">${markdown(r.calculation,r)}</div></details>`;
if(r.substitutions?.length)html+=`<details class="detail-extra"><summary>食材替代</summary>${r.substitutions.map(t=>'<p>'+esc(t)+'</p>').join('')}</details>`;
if(r.tools)html+=`<details class="detail-extra"><summary>要用的工具</summary><p>${esc(r.tools)}</p></details>`;return html;}
function actionMarkup(r,index){const items=Reading.actionsFor(r,index,r.editorial?scaled:null);if(items.length===1&&!items[0].title)return `<div class="reading-paragraphs"><p>${esc(items[0].body)}</p></div>`;return `<ol class="reading-actions reading-book">${items.map((a,i)=>`<li class="reading-item"><span class="reading-number" aria-hidden="true">${String(i+1).padStart(2,'0')}</span><span class="reading-copy">${a.title?`<strong>${esc(a.title)}</strong>`:''}<span class="reading-body">${esc(a.body)}</span></span></li>`).join('')}</ol>`;}
function stepsContent(r){let group='';return r.steps.map((s,i)=>{const head=s.group&&s.group!==group?`<h2 style="margin-top:24px">${esc(s.group)}</h2>`:'';group=s.group;return `${head}<article class="detail-step">${r.id==='tomato-noodles'?processPhoto(i):''}<div class="detail-step-heading"><span class="step-number">${i+1}</span><h3>${esc(Reading.headingFor(r,i))}</h3></div>${actionMarkup(r,i)}${s.state?`<p class="step-observe">${esc(s.state)}</p>`:''}</article>`;}).join('');}
function renderDetail(r){const tabs=r.editorial?['备菜','步骤','为什么']:['备菜','步骤','原文'];let body=recipeTab==='备菜'?ingredientContent(r):recipeTab==='步骤'?stepsContent(r):recipeTab==='为什么'?(r.why||[]).map(([h,p])=>`<article class="why-card"><h3>${esc(h)}</h3><p>${esc(p)}</p></article>`).join(''):`<div class="prose">${markdown(r.raw,r)}</div>`;$('#screen').innerHTML=`<div class="detail-top">${photo(r)}<div class="detail-nav"><button class="icon-button" data-back aria-label="返回">${icon('back')}</button><button class="icon-button ${S.favorites.includes(r.id)?'saved':''}" data-favorite="${r.id}" aria-pressed="${S.favorites.includes(r.id)}" aria-label="${S.favorites.includes(r.id)?'取消收藏':'收藏'}${esc(r.name)}">${icon('heart')}</button></div></div><div class="detail-body"><h1>${esc(r.name)}</h1><div class="detail-meta">${meta(r)}<span>${r.steps.length} 步</span></div><div class="detail-tabs" role="tablist" aria-label="菜谱内容">${tabs.map(t=>`<button role="tab" aria-selected="${recipeTab===t}" class="${recipeTab===t?'active':''}" data-recipe-tab="${t}">${t}</button>`).join('')}</div><section role="tabpanel">${body}</section>${r.sourceUrl?`<a class="source-link" href="${esc(r.sourceUrl)}" target="_blank" rel="noopener noreferrer">HowToCook · 查看原方 ↗</a>`:''}</div><div class="detail-actions">${misses(r).length?`<button class="bag-button" id="add-missing">${icon('bag')}补食材</button>`:''}<button class="primary" id="start-cooking">开始做菜 ${icon('arrow')}</button></div>`;}
function stopTimer(){clearInterval(timerInterval);timerInterval=null;timerDeadline=0;timerLeft=0;timerRecipe='';timerStep=-1;}
function formatTime(n){const h=Math.floor(n/3600),m=Math.floor(n%3600/60),s=n%60;return (h?String(h).padStart(2,'0')+':':'')+String(m).padStart(2,'0')+':'+String(s).padStart(2,'0');}
function renderCook(r){const s=r.steps[stepIndex];stopTimer();if(!s){if(!S.cooked.some(c=>c.id===r.id)){S.cooked.push({id:r.id,at:new Date().toISOString()});save();}$('#screen').innerHTML=`<div class="cook-done">${photo(r)}<h1>开饭啦。</h1><p>这一餐，是你亲手做的。</p><button class="primary full" data-go="home">返回首页 ${icon('home')}</button></div>`;return;}
timerRecipe=r.id;timerStep=stepIndex;timerLeft=s.seconds||0;$('#screen').innerHTML=`<header class="cook-header"><button class="icon-button" data-end-cook aria-label="退出做菜">${icon('x')}</button><span>CookXuan · 厨房手册</span><span>${stepIndex+1} / ${r.steps.length}</span></header><div class="cook-progress"><div style="width:${(stepIndex+1)/r.steps.length*100}%"></div></div><section class="cook-notebook-head"><div><h2>${esc(r.name)}</h2><p>${r.time?'约 '+r.time+' 分钟 · ':''}${r.editorial?S.servings+' 人份':r.category}</p></div><div class="cook-notebook-thumb">${r.id==='tomato-noodles'?processPhoto(stepIndex):photo(r)}</div></section><h1 class="cook-title">${esc(Reading.headingFor(r,stepIndex))}</h1>${actionMarkup(r,stepIndex)}${s.state?`<p class="cook-observe">${esc(s.state)}</p>`:''}${s.seconds?`<div class="timer"><div><time id="timer-display">${formatTime(s.seconds)}</time></div><button id="toggle-timer">计时</button><button id="reset-timer" aria-label="重置计时">${icon('refresh')}</button></div>`:''}<div class="cook-footer"><button class="outline" id="previous-step" ${stepIndex===0?'disabled':''}>上一步</button><button class="primary" id="next-step">${stepIndex===r.steps.length-1?'做好了':'下一步'}${icon('arrow')}</button></div>`;}
function tick(){timerLeft=Math.max(0,Math.ceil((timerDeadline-Date.now())/1000));const el=$('#timer-display');if(el)el.textContent=formatTime(timerLeft);if(!timerLeft){clearInterval(timerInterval);timerInterval=null;timerDeadline=0;if($('#toggle-timer'))$('#toggle-timer').textContent='再计时';navigator.vibrate?.(180);toast('时间到了');}}
function toggleTimer(){if(timerInterval){timerLeft=Math.max(0,Math.ceil((timerDeadline-Date.now())/1000));clearInterval(timerInterval);timerInterval=null;timerDeadline=0;$('#toggle-timer').textContent='继续';return;}if(timerLeft<=0)timerLeft=byId.get(timerRecipe).steps[timerStep].seconds;timerDeadline=Date.now()+timerLeft*1000;timerInterval=setInterval(tick,250);$('#toggle-timer').textContent='暂停';tick();}
function requestWakeLock(){if(navigator.wakeLock&&!wakeLock)navigator.wakeLock.request('screen').then(l=>wakeLock=l).catch(()=>{});}
function releaseWakeLock(){wakeLock?.release().catch(()=>{});wakeLock=null;}
function addShopping(names){let count=0;for(const name of names){const item=S.shopping.find(i=>i.name===name);if(item){if(item.done){item.done=false;count++;}}else if(S.shopping.length<100){S.shopping.push({name,done:false});count++;}}save();return count;}
async function install(){if(installPrompt){await installPrompt.prompt();installPrompt=null;return;}const ios=/iPad|iPhone|iPod/.test(navigator.userAgent);openSheet(`<h2>添加到桌面</h2><div class="install-step"><span>1</span><p>${ios?'用 Safari 打开 CookXuan':'用手机浏览器打开 CookXuan'}</p></div><div class="install-step"><span>2</span><p>${ios?'点「分享」，选择「添加到主屏幕」':'打开菜单，选择「安装应用」或「添加到主屏幕」'}</p></div>`);}
function sourceInfo(){openSheet(`<h2>菜谱来源</h2><p>${D.meta.sourceRecipeCount} 道 HowToCook 原方，${D.meta.curatedRecipeCount} 道精选改编。</p><div class="suggestions">${Object.entries(D.meta.categories).map(([name,count])=>`<button class="suggestion" data-source-category="${name}">${name} ${count}</button>`).join('')}</div><p><a href="https://github.com/Anduin2017/HowToCook" target="_blank" rel="noopener noreferrer">Anduin2017 / HowToCook ↗</a></p>`);}
function learn(){openSheet(`<h2>厨房小课堂</h2>${D.tips.map((t,i)=>`<button class="list-recipe" data-tip="${i}"><span class="list-info"><h3>${esc(t.name)}</h3></span>${icon('arrow')}</button>`).join('')}`);}
async function copyShopping(){const text=S.shopping.filter(i=>!i.done).map(i=>'□ '+i.name+(english(i.name)?' / '+english(i.name):'')).join('\n');if(!text){toast('已经买齐了');return;}try{await navigator.clipboard.writeText(text);toast('采购单已复制');}catch{const blob=new Blob([text],{type:'text/plain;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='CookXuan-采购单.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);toast('采购单已导出');}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
if(b.dataset.go){if(b.dataset.go==='reset-library'){query='';category='全部';filter='全部';matching=false;limit=24;renderLibrary();}else go(b.dataset.go);return;}
if(b.dataset.recipe){go('recipe/'+b.dataset.recipe);return;}if(b.dataset.favorite){toggleFavorite(b.dataset.favorite);return;}
if(b.hasAttribute('data-back')){back();return;}if(b.hasAttribute('data-close-sheet')){$('#sheet').close();return;}
if(b.hasAttribute('data-open-pantry')){openPantry();return;}if(b.dataset.add){addFood(b.dataset.add);return;}
if(b.dataset.remove){S.pantry=S.pantry.filter(n=>n!==b.dataset.remove);save();refreshPantry();return;}
if(b.dataset.seasoning){const n=b.dataset.seasoning;S.seasonings=S.seasonings.includes(n)?S.seasonings.filter(x=>x!==n):[...S.seasonings,n];save();refreshPantry();return;}
if(b.hasAttribute('data-match')){if(!S.pantry.length){toast('先放一种食材进冰箱');return;}if($('#sheet').open)$('#sheet').close();matching=true;query='';category='全部';filter='全部';limit=24;if(route==='library')renderLibrary();else go('library');return;}
if(b.dataset.category){category=b.dataset.category;limit=24;$$('[data-category]').forEach(el=>{el.classList.toggle('active',el.dataset.category===category);el.setAttribute('aria-pressed',el.dataset.category===category);});updateLibraryResults();return;}
if(b.dataset.sourceCategory){category=b.dataset.sourceCategory;query='';filter='全部';matching=false;limit=24;$('#sheet').close();if(route==='library')renderLibrary();else go('library');return;}
if(b.dataset.filter){filter=b.dataset.filter;limit=24;$$('[data-filter]').forEach(el=>{el.classList.toggle('active',el.dataset.filter===filter);el.setAttribute('aria-pressed',el.dataset.filter===filter);});updateLibraryResults();return;}
if(b.dataset.pantryTab){pantryTab=b.dataset.pantryTab;renderPantry();return;}if(b.dataset.myTab){myTab=b.dataset.myTab;renderMe();return;}
if(b.dataset.recipeTab){recipeTab=b.dataset.recipeTab;const y=window.scrollY;renderDetail(byId.get(currentRecipeId));window.scrollTo(0,y);return;}
if(b.dataset.serving){S.servings=Math.max(1,Math.min(6,S.servings+Number(b.dataset.serving)));save();const y=scrollY;renderDetail(byId.get(currentRecipeId));window.scrollTo(0,y);return;}
if(b.dataset.removeShopping!==undefined){S.shopping.splice(+b.dataset.removeShopping,1);save();renderPantry();return;}
if(b.dataset.tip!==undefined){const tip=D.tips[+b.dataset.tip];if(tip){$('#sheet-content').innerHTML=`<h2>${esc(tip.name)}</h2><div class="prose">${markdown(tip.raw)}</div>`;$('#sheet').scrollTop=0;}return;}
if(b.hasAttribute('data-end-cook')){go('recipe/'+currentRecipeId,true);return;}
switch(b.id){case 'shuffle':featuredOffset=(featuredOffset+1)%4;{const y=scrollY;renderHome();window.scrollTo(0,y);}break;case 'clear-search':query='';$('#recipe-search').value='';limit=24;updateLibraryResults();$('#recipe-search').focus();break;case 'load-more':limit+=24;updateLibraryResults();break;case 'show-all':matching=false;renderLibrary();break;case 'install-app':install();break;case 'source-info':sourceInfo();break;case 'learn':learn();break;case 'start-cooking':stepIndex=0;go('cook/'+currentRecipeId);break;case 'add-missing':{const n=addShopping(misses(byId.get(currentRecipeId)).map(i=>i.name));toast(n?`已加入采购单 · ${n} 样`:'已经记在采购单里了');break;}case 'previous-step':if(stepIndex>0){stepIndex--;renderCook(byId.get(currentRecipeId));window.scrollTo(0,0);}break;case 'next-step':stepIndex++;renderCook(byId.get(currentRecipeId));window.scrollTo(0,0);break;case 'toggle-timer':toggleTimer();break;case 'reset-timer':{const id=timerRecipe,index=timerStep;stopTimer();timerRecipe=id;timerStep=index;timerLeft=byId.get(id).steps[index].seconds;$('#timer-display').textContent=formatTime(timerLeft);$('#toggle-timer').textContent='计时';break;}case 'copy-shopping':copyShopping();break;case 'move-bought':{let count=0;for(const item of S.shopping.filter(x=>x.done)){const target=D.seasonings.includes(item.name)?S.seasonings:S.pantry;if(!target.includes(item.name)&&target.length<60)target.push(item.name);else if(target.length>=60)continue;S.shopping=S.shopping.filter(i=>i!==item);count++;}save();renderPantry();toast(count?`放进冰箱了 · ${count} 样`:'先勾选买好的食材');break;}}
});
document.addEventListener('submit',e=>{if(e.target.id==='ingredient-form'){e.preventDefault();const input=$('#ingredient-input',e.target);addFood(input.value);}else if(e.target.id==='shopping-form'){e.preventDefault();const input=$('#shopping-input');if(!input.value.trim())return;addShopping([canonical(input.value)]);renderPantry();toast('记在采购单里了');}});
document.addEventListener('input',e=>{if(e.target.id==='recipe-search'){query=e.target.value;limit=24;clearTimeout(searchHandle);searchHandle=setTimeout(updateLibraryResults,100);}});
document.addEventListener('change',e=>{if(e.target.dataset.buy!==undefined){const item=S.shopping[+e.target.dataset.buy];if(item){item.done=e.target.checked;save();renderPantry();}}});
document.addEventListener('keydown',e=>{if(e.target.matches('[role="tab"]')&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const tabs=$$('[role="tab"]'),index=tabs.indexOf(e.target),target=tabs[(index+(e.key==='ArrowRight'?1:tabs.length-1))%tabs.length];target.click();$(`[data-recipe-tab="${target.dataset.recipeTab}"]`)?.focus();}});
document.addEventListener('error',e=>{const img=e.target;if(img.tagName==='IMG'&&img.closest('.recipe-photo')){const parent=img.closest('.recipe-photo');parent.className='recipe-photo placeholder';parent.innerHTML=icon('chef');}},true);
$('#sheet').addEventListener('click',e=>{if(e.target!==$('#sheet'))return;const box=$('#sheet').getBoundingClientRect();if(e.clientX<box.left||e.clientX>box.right||e.clientY<box.top||e.clientY>box.bottom)$('#sheet').close();});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
window.addEventListener('popstate',()=>renderRoute(location.hash.slice(1)||'home'));
window.addEventListener('hashchange',()=>{const r=location.hash.slice(1)||'home';if(r!==route)renderRoute(r);});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&route.startsWith('cook/')){if(timerDeadline)tick();requestWakeLock();}});
if('serviceWorker' in navigator&&/^https?:$/.test(location.protocol))window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
renderRoute(initialRoute);
})();
